let macroRunning=false,macroUpdated=0;
async function loadMacro(force=false){if(macroRunning||(!force&&Date.now()-macroUpdated<900000))return;macroRunning=true;$('macro-status').textContent='正在获取宏观数据…';$('macro-cards').innerHTML='';$('macro-rule').textContent='';try{const response=await fetch('/api/macro',{signal:AbortSignal.timeout(20000)});if(!response.ok)throw Error();const d=await response.json();macroUpdated=Date.now();$('macro-status').textContent=d.headline+' · 有效 '+d.coverage+' / 3'+(d.asOf?' · 共同观察日期 '+d.asOf:'');$('macro-cards').innerHTML=d.cards.map(c=>`<article class="macro-card"><h3>${esc(c.label)}</h3><strong>${c.status==='ok'?c.value.toFixed(2)+' '+esc(c.unit):'—'}</strong><p class="${c.direction==='rising'?'no':c.direction==='easing'?'yes':'muted'}">${c.status==='ok'?'20个观测变化 '+(c.change>0?'+':'')+c.change.toFixed(2)+' '+esc(c.deltaUnit)+' · '+({rising:'压力上升',easing:'压力缓和',stable:'幅度温和'}[c.direction]):({missing:'来源暂不可用',stale:'数据过期，未参与判断',insufficient:'日期未对齐或历史不足'}[c.status])}</p><p class="muted">${c.status==='ok'?esc(c.previousDate)+' → '+esc(c.date):''}<br>来源最新日期：${esc(c.latestDate||'未知')}</p><a href="${esc(c.url)}" target="_blank" rel="noopener">FRED · ${esc(c.id)}</a></article>`).join('');$('macro-rule').textContent=d.note;}catch{$('macro-status').textContent='宏观数据暂不可用，请重试。';}finally{macroRunning=false;}}
$('refresh-macro').onclick=()=>loadMacro(true);loadMacro();setInterval(()=>{if(!document.hidden)loadMacro();},900000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadMacro();});
